import { talkingRobotMarkup } from './talking-robot.js';

const escapeHTML = value => String(value).replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character]));

// These are goal prompts, not a replacement for the interactive first-level guide.
// Only the first four Explorer puzzles reveal their short teaching sequence.
export function missionTip(mission, chapterIndex, lang = 'en') {
  const pair = (chapterIndex === 0 ? openingTips[mission.id] : null) || tips[mission.id];
  const languageIndex = lang === 'tr' ? 1 : 0;
  return pair?.[languageIndex] || mission.objective?.[languageIndex] || (languageIndex === 1
    ? 'Birlikte keşfedelim! Çim yolunu incele ve beni görevimizin hedefine ulaştıracak bir program hazırla.'
    : 'Let’s explore together! Look at the grass path and build a program that helps me reach our mission goal.');
}

export function missionCompanionMarkup(mission, chapterIndex, lang = 'en') {
  const guideLabel = lang === 'tr' ? 'KAŞİF’in görev ipucu' : 'KAŞİF’s mission tip';
  return `<aside class="mission-companion" aria-label="${escapeHTML(guideLabel)}"><div class="companion-bubble"><span class="companion-name">KAŞİF</span><p class="companion-tip">${escapeHTML(missionTip(mission, chapterIndex, lang))}</p></div><span class="companion-robot">${talkingRobotMarkup({ mood: 'happy', id: 'companion' })}</span></aside>`;
}
